intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english, AVG(t2.review_score) AS avg_review_score, (SELECT AVG(review_score) FROM vw_entregas_retrasos) AS avg_global_review_score, SUM(CASE WHEN t2.review_score < (SELECT AVG(review_score) FROM vw_entregas_retrasos) THEN 1 ELSE 0 END) * 100.0 / COUNT(t2.review_score) AS pct_late_deliveries FROM product_category_translation t1 LEFT JOIN vw_ventas_pedido t2 ON t1.product_category_name = t2.categoria_ingles WHERE t2.review_score IS NOT NULL GROUP BY t1.product_category_name_english HAVING COUNT(t2.review_score) >= 100 AND avg_review_score < avg_global_review_score AND pct_late_deliveries < (SELECT AVG(review_score) FROM vw_entregas_retrasos) * 100.0 / COUNT(t2.review_score)"
}
